const vsteps = (cur) => `<div style="display:grid;gap:2px">${STEPS.map(([s, d], i) => `<div style="display:flex;gap:12px;padding:9px 10px;border-radius:var(--radius);position:relative;${i === cur ? "background:color-mix(in oklab,var(--primary) 10%,var(--surface))" : ""}">${i < STEPS.length - 1 ? `<span style="position:absolute;left:22px;top:36px;bottom:-8px;width:2px;background:${i < cur ? "var(--primary)" : "var(--border)"}"></span>` : ""}<span style="width:26px;height:26px;border-radius:50%;display:grid;place-items:center;font:700 12px var(--font-b);flex:none;position:relative;${i < cur ? "background:var(--primary);color:var(--on-primary)" : i === cur ? "border:2px solid var(--primary);color:var(--primary);background:var(--surface)" : "border:1.5px solid var(--border);color:var(--muted);background:var(--surface)"}">${i < cur ? ic("check", 13) : i + 1}</span><div style="line-height:1.3;min-width:0"><div style="font-size:13px;font-weight:${i === cur ? 700 : 500};${i > cur ? "color:var(--muted)" : ""}">${s}</div><div class="muted" style="font-size:12px">${i < cur ? "Done · " : ""}${d}</div></div></div>`).join("")}</div>`;
const okIc = `<span style="margin-left:auto;color:var(--primary);display:inline-flex">${ic("check", 16)}</span>`;
const fld = (label, icon, val, hint) => `<div class="field" style="align-content:start"><label>${label}</label><div class="input filled" style="gap:8px">${icon ? `<span class="muted" style="display:inline-flex">${ic(icon, 15)}</span>` : ""}<span style="white-space:nowrap">${val}</span>${okIc}</div>${hint ? `<div class="muted" style="font-size:12px">${hint}</div>` : ""}</div>`;
const radio = (on) => `<span style="width:18px;height:18px;border-radius:50%;flex:none;border:2px solid ${on ? "var(--primary)" : "color-mix(in oklab,var(--muted) 60%,var(--surface))"};display:grid;place-items:center">${on ? '<span style="width:8px;height:8px;border-radius:50%;background:var(--primary)"></span>' : ""}</span>`;
const toggle = (on) => `<span style="width:36px;height:20px;border-radius:999px;flex:none;padding:2px;display:flex;${on ? "justify-content:flex-end;background:var(--primary)" : "background:color-mix(in oklab,var(--text) 15%,var(--surface))"}"><span style="width:16px;height:16px;border-radius:50%;background:var(--surface)"></span></span>`;
